// Validate Request
// Validates the webhook payload and merges it with the values from the "Config" node.
// Output: one item with { action: 'ingest' | 'ask' | 'invalid', ...config, ...payload }.
// Invalid requests are NOT thrown — they are routed to the "Respond: Error" node (HTTP 400).

const MAX_DOCUMENTS = 100;
const MAX_DOC_CHARS = 200000;
const MAX_QUESTION_CHARS = 2000;

const item = $input.first().json;
const body = item.body && typeof item.body === 'object' && !Array.isArray(item.body) ? item.body : {};

const toNumber = (value, fallback) => {
  const n = Number(value);
  return Number.isFinite(n) ? n : fallback;
};
const clamp = (n, min, max) => Math.min(max, Math.max(min, n));

const config = {
  qdrantUrl: String(item.qdrantUrl || '').trim().replace(/\/+$/, ''),
  collection: String(item.collection || '').trim(),
  embeddingModel: String(item.embeddingModel || 'text-embedding-3-small'),
  chatModel: String(item.chatModel || 'gpt-4o-mini'),
  topK: clamp(Math.round(toNumber(item.topK, 5)), 1, 20),
  minScore: clamp(toNumber(item.minScore, 0.3), 0, 1),
  chunkSize: clamp(Math.round(toNumber(item.chunkSize, 1000)), 200, 8000),
  chunkOverlap: Math.max(0, Math.round(toNumber(item.chunkOverlap, 150))),
  maxContextChars: clamp(Math.round(toNumber(item.maxContextChars, 12000)), 1000, 100000),
};
// Overlap must be clearly smaller than the chunk, otherwise chunking would not progress.
config.chunkOverlap = Math.min(config.chunkOverlap, Math.floor(config.chunkSize / 2));

const errors = [];
if (!/^https?:\/\//.test(config.qdrantUrl)) errors.push('Config: qdrantUrl must start with http:// or https://');
if (!/^[A-Za-z0-9_-]+$/.test(config.collection)) errors.push('Config: collection must contain only letters, digits, "_" or "-"');

const action = String(body.action || '').trim().toLowerCase();
const out = { ...config, action };

if (action === 'ingest') {
  const docs = body.documents;
  if (!Array.isArray(docs) || docs.length === 0) {
    errors.push('"documents" must be a non-empty array');
  } else if (docs.length > MAX_DOCUMENTS) {
    errors.push(`Too many documents in one request (max ${MAX_DOCUMENTS})`);
  } else {
    out.documents = [];
    docs.forEach((doc, i) => {
      if (!doc || typeof doc !== 'object') return errors.push(`documents[${i}] must be an object`);
      const text = typeof doc.text === 'string' ? doc.text.trim() : '';
      if (!text) return errors.push(`documents[${i}].text must be a non-empty string`);
      if (text.length > MAX_DOC_CHARS) return errors.push(`documents[${i}].text is longer than ${MAX_DOC_CHARS} chars`);
      const title = String(doc.title || `Document ${i + 1}`).trim();
      const slug = title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') || `doc-${i + 1}`;
      out.documents.push({
        id: String(doc.id || slug),
        title,
        source: doc.source ? String(doc.source) : null,
        metadata: doc.metadata && typeof doc.metadata === 'object' ? doc.metadata : {},
        text,
      });
    });
  }
} else if (action === 'ask') {
  const question = typeof body.question === 'string' ? body.question.trim() : '';
  if (!question) errors.push('"question" must be a non-empty string');
  else if (question.length > MAX_QUESTION_CHARS) errors.push(`"question" is longer than ${MAX_QUESTION_CHARS} chars`);
  out.question = question;
  if (body.topK !== undefined) out.topK = clamp(Math.round(toNumber(body.topK, config.topK)), 1, 20);
} else {
  errors.push('"action" must be "ingest" or "ask"');
}

if (errors.length) {
  return [{ json: { action: 'invalid', statusCode: 400, error: errors.join('; ') } }];
}
return [{ json: out }];

// Chunk Documents
// Splits every document into overlapping chunks (paragraph > sentence > word boundaries)
// and gives each chunk a deterministic UUID, so re-ingesting a document overwrites it.

const MAX_CHUNKS = 2000; // one embeddings request; OpenAI accepts up to 2048 inputs

const cfg = $input.first().json;
const size = cfg.chunkSize;
const overlap = cfg.chunkOverlap;

function normalize(text) {
  return text
    .replace(/\r\n?/g, '\n')
    .replace(/[ \t\f\v]+/g, ' ')
    .replace(/ ?\n ?/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function chunkText(text) {
  const clean = normalize(text);
  if (clean.length <= size) return clean ? [clean] : [];
  const chunks = [];
  let start = 0;
  while (start < clean.length) {
    let end = Math.min(start + size, clean.length);
    if (end < clean.length) {
      // Cut at the "nicest" boundary found in the second half of the window.
      const windowText = clean.slice(start, end);
      const minCut = Math.floor(size * 0.5);
      for (const sep of ['\n\n', '\n', '. ', '? ', '! ', ' ']) {
        const idx = windowText.lastIndexOf(sep);
        if (idx >= minCut) { end = start + idx + sep.length; break; }
      }
    }
    const piece = clean.slice(start, end).trim();
    if (piece) chunks.push(piece);
    if (end >= clean.length) break;
    // Step back by `overlap` chars, snapped forward to the next word start.
    let next = end - overlap;
    if (overlap > 0) {
      const space = clean.indexOf(' ', next);
      if (space !== -1 && space < end) next = space + 1;
    }
    start = Math.max(next, start + 1);
  }
  return chunks;
}

// FNV-1a 32-bit hash; four seeded rounds give 128 bits formatted as a UUID (Qdrant point id).
function fnv1a(str, seed) {
  let h = 0x811c9dc5 ^ seed;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return h >>> 0;
}
function uuidFrom(str) {
  const hex = [1, 2, 3, 4].map((s) => fnv1a(str, s * 0x9e3779b1).toString(16).padStart(8, '0')).join('');
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20, 32)}`;
}

const chunks = [];
for (const doc of cfg.documents) {
  chunkText(doc.text).forEach((text, chunkIndex) => {
    chunks.push({
      id: uuidFrom(`${doc.id}#${chunkIndex}`),
      docId: doc.id,
      title: doc.title,
      source: doc.source,
      metadata: doc.metadata,
      chunkIndex,
      text,
    });
  });
}

if (chunks.length === 0) throw new Error('No text to index after normalisation');
if (chunks.length > MAX_CHUNKS) {
  throw new Error(`Too many chunks (${chunks.length} > ${MAX_CHUNKS}). Send fewer documents per request or raise chunkSize.`);
}

return [{
  json: {
    qdrantUrl: cfg.qdrantUrl,
    collection: cfg.collection,
    embeddingModel: cfg.embeddingModel,
    docIds: [...new Set(chunks.map((c) => c.docId))],
    documentCount: cfg.documents.length,
    chunkCount: chunks.length,
    chunks,
  },
}];

// Build Qdrant Points
// Pairs the OpenAI embeddings response with the chunks from "Chunk Documents"
// and produces the body for Qdrant's PUT /collections/{name}/points.

const chunkData = $('Chunk Documents').first().json;
const response = $input.first().json;

if (!response || !Array.isArray(response.data)) {
  throw new Error('Embeddings response has no "data" array: ' + JSON.stringify(response).slice(0, 300));
}
const chunks = chunkData.chunks;
if (response.data.length !== chunks.length) {
  throw new Error(`Got ${response.data.length} embeddings for ${chunks.length} chunks`);
}

// OpenAI returns an `index` per embedding — never rely on array order alone.
const vectors = [...response.data].sort((a, b) => a.index - b.index).map((d) => d.embedding);
const dim = vectors[0] && vectors[0].length;
if (!dim || vectors.some((v) => !Array.isArray(v) || v.length !== dim)) {
  throw new Error('Embeddings have missing or inconsistent dimensions');
}

const ingestedAt = new Date().toISOString();
const points = chunks.map((chunk, i) => ({
  id: chunk.id,
  vector: vectors[i],
  payload: {
    text: chunk.text,
    docId: chunk.docId,
    title: chunk.title,
    source: chunk.source,
    chunkIndex: chunk.chunkIndex,
    metadata: chunk.metadata,
    ingestedAt,
  },
}));

return [{
  json: {
    qdrantUrl: chunkData.qdrantUrl,
    collection: chunkData.collection,
    documentCount: chunkData.documentCount,
    chunkCount: chunkData.chunkCount,
    vectorSize: dim,
    points,
  },
}];

// Build Prompt
// Turns Qdrant search hits into a numbered context block and the chat messages for the LLM.
// Hits below `minScore` are dropped; if nothing relevant is left, hasContext = false and the
// workflow answers "not found" without calling the LLM (saves tokens, avoids hallucinations).

const req = $('Validate Request').first().json;
const hits = Array.isArray($input.first().json.result) ? $input.first().json.result : [];

const seen = new Set();
const sources = [];
let used = 0;
for (const hit of [...hits].sort((a, b) => b.score - a.score)) {
  const p = hit.payload || {};
  const text = typeof p.text === 'string' ? p.text.trim() : '';
  if (!text || hit.score < req.minScore || seen.has(text)) continue;
  if (used + text.length > req.maxContextChars && sources.length > 0) break;
  seen.add(text);
  used += text.length;
  sources.push({
    n: sources.length + 1,
    title: p.title || 'Untitled',
    source: p.source || null,
    docId: p.docId || null,
    chunkIndex: p.chunkIndex ?? null,
    score: Math.round(hit.score * 1000) / 1000,
    text,
  });
}

const systemPrompt = [
  'You are a helpful assistant that answers questions about the company using ONLY the provided context.',
  'Rules:',
  '- If the answer is not in the context, say you could not find it in the company documents. Do not guess.',
  '- Cite the sources you used with their number in square brackets, e.g. [1] or [2][3].',
  '- Be concise and answer in the same language as the question.',
].join('\n');

const context = sources.map((s) => `[${s.n}] ${s.title}${s.source ? ` (${s.source})` : ''}\n${s.text}`).join('\n\n---\n\n');

return [{
  json: {
    hasContext: sources.length > 0,
    question: req.question,
    chatModel: req.chatModel,
    sources,
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: `Context:\n${context}\n\nQuestion: ${req.question}` },
    ],
  },
}];

// Format Answer
// Extracts the LLM answer and keeps only the sources it actually cited ([n]).

const prompt = $('Build Prompt').first().json;
const completion = $input.first().json;

const content = completion && completion.choices && completion.choices[0] && completion.choices[0].message
  ? String(completion.choices[0].message.content || '').trim()
  : '';
if (!content) {
  throw new Error('LLM returned an empty answer: ' + JSON.stringify(completion).slice(0, 300));
}

const cited = new Set();
for (const m of content.matchAll(/\[(\d{1,3})\]/g)) cited.add(Number(m[1]));
const citedSources = prompt.sources.filter((s) => cited.has(s.n));

return [{
  json: {
    answer: content,
    grounded: citedSources.length > 0,
    // Fall back to all retrieved sources when the model forgot to cite.
    sources: (citedSources.length ? citedSources : prompt.sources).map(({ text, ...meta }) => ({
      ...meta,
      snippet: text.length > 240 ? text.slice(0, 240) + '…' : text,
    })),
    model: completion.model || prompt.chatModel,
    usage: completion.usage || null,
  },
}];

// No Context Answer
// Returned when vector search found nothing above minScore — the LLM is not called.

const prompt = $input.first().json;

return [{
  json: {
    answer: "I couldn't find information about this in the company documents. Please rephrase the question or contact the responsible team.",
    grounded: false,
    sources: [],
    question: prompt.question,
  },
}];
